g_Sustain4VelAdd.DISTANCE := -(fSetPos - dLastCoord);



g_Sustain5VelAdd.ENABLE := g_bFrontAxis2VelAddEnable AND NOT g_bFrontSupportPendingFlag AND NOT g_bFrontSustainAxis2CloseVelAdd; 
g_Sustain5VelAdd.VELADDITIVEMODE := 1;
g_Sustain5VelAdd.DISTANCE := -(fSetPos - dLastCoord);

g_Sustain6VelAdd.ENABLE := g_bFrontAxis3VelAddEnable AND NOT g_bFrontSupportPendingFlag AND NOT g_bFrontSustainAxis3CloseVelAdd;
g_Sustain6VelAdd.VELADDITIVEMODE := 1;
g_Sustain6VelAdd.DISTANCE := -(fSetPos - dLastCoord);

g_FrontSustain4VelAdd.ENABLE := g_bFrontAxis4VelAddEnable AND NOT g_bFrontSupportPendingFlag AND NOT g_bFrontSustainAxis4CloseVelAdd;
g_FrontSustain4VelAdd.VELADDITIVEMODE := 1;
g_FrontSustain4VelAdd.DISTANCE := -(fSetPos - dLastCoord);




